const listRankingCandidates = `-- name: ListRankingCandidates :many
SELECT a.id, a.title, a.summary, a.published_at, a.classification, s.name AS source_name, s.kind AS source_kind
FROM articles a
JOIN sources s ON s.id = a.source_id
WHERE a.duplicate_of IS NULL
  AND a.classified_at IS NOT NULL
  AND a.published_at > $1
  AND NOT EXISTS (
    SELECT 1 FROM personal_analyses pa
    WHERE pa.article_id = a.id AND pa.user_id = $2 AND pa.method = 'llm'
  )
ORDER BY a.published_at DESC
LIMIT $3
`

